const countries=['china','korea','mongolia','japan','philippines','indonesia'];
export const controls=['province-layer','prefecture-layer','other-layer','label-layer','satellite-layer','satellite-opacity','capital-layer','water-layer','k-province-layer','k-prefecture-layer','k-label-layer','k-capital-layer','m-province-layer','m-district-layer','m-label-layer','m-capital-layer','j-province-layer','j-label-layer','ph-province-layer','ph-second-layer','ph-label-layer','id-province-layer','id-second-layer','id-label-layer'];
export function validate(value){
 if(!value||value.v!==1||!countries.includes(value.country)||!Array.isArray(value.center)||value.center.length!==2||!value.center.every(Number.isFinite)||value.center[0]<45||value.center[0]>165||value.center[1]<-15||value.center[1]>68||!Number.isFinite(value.zoom)||value.zoom<1||value.zoom>16)return null;
 const layers={};for(const id of controls){const v=value.layers?.[id];if(id==='satellite-opacity'){if(Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=100)layers[id]=String(v);}else if(typeof v==='boolean')layers[id]=v;}
 return {v:1,country:value.country,center:value.center,zoom:value.zoom,selection:typeof value.selection==='string'||typeof value.selection==='number'?String(value.selection).slice(0,80):null,scope:['KP','KR'].includes(value.scope)?value.scope:'',mode:value.mode===2?2:1,locked:value.locked===true,language:['en','local','both'].includes(value.language)?value.language:'both',layers};
}
export function fromHash(hash){try{const m=/^#(china|korea|mongolia|japan|philippines|indonesia)\/view=(.*)$/i.exec(hash);if(!m||m[2].length>10000)return null;const value=validate(JSON.parse(decodeURIComponent(m[2])));return value?.country===m[1].toLowerCase()?value:null;}catch{return null;}}
export function hashFor(view){const valid=validate(view);return valid?'#'+valid.country+'/view='+encodeURIComponent(JSON.stringify(valid)):null;}
export function read(country,storage){try{return validate(JSON.parse(storage.getItem('boundary-atlas-view-v1-'+country)));}catch{return null;}}
export function write(view,storage){const valid=validate(view);if(!valid)return;try{storage.setItem('boundary-atlas-view-v1-'+valid.country,JSON.stringify(valid));}catch{}}
